import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import com.sky.entity.OrderDetail;
import com.sky.entity.Orders;
import com.sky.exception.OrderBusinessException;
import com.sky.mapper.OrderDetailMapper;
import com.sky.mapper.OrderMapper;
import com.sky.vo.OrderVO;

@ExtendWith(MockitoExtension.class)
class OrderServiceImplTest {

    @InjectMocks
    private OrderServiceImpl orderService;

    @Mock
    private OrderMapper orderMapper;

    @Mock
    private OrderDetailMapper orderDetailMapper;

    @Test
    @DisplayName("正向测试：当订单存在时，details方法应正确返回OrderVO")
    void testDetails_OrderExists_ShouldReturnOrderVO() {
        // Arrange
        Long orderId = 1L;
        Orders mockOrder = new Orders();
        mockOrder.setId(orderId);
        mockOrder.setNumber("12345");

        OrderDetail mockDetail = new OrderDetail();
        mockDetail.setOrderId(orderId);

        when(orderMapper.getById(orderId)).thenReturn(mockOrder);
        when(orderDetailMapper.getByOrderId(orderId)).thenReturn(Arrays.asList(mockDetail));

        // Act
        OrderVO result = orderService.details(orderId);

        // Assert
        assertNotNull(result);
        assertEquals(orderId, result.getId());
        assertNotNull(result.getOrderDetailList());
        assertEquals(1, result.getOrderDetailList().size());

        // Verify
        verify(orderMapper).getById(orderId);
        verify(orderDetailMapper).getByOrderId(orderId);
    }

    @Test
    @DisplayName("边界测试：当订单不存在时，details方法应抛出OrderBusinessException而非NullPointerException")
    void testDetails_OrderNotFound_ShouldThrowOrderBusinessException() {
        // Arrange
        Long nonExistentOrderId = 999L;
        when(orderMapper.getById(nonExistentOrderId)).thenReturn(null);

        // Act & Assert
        OrderBusinessException exception = assertThrows(OrderBusinessException.class, () -> {
            orderService.details(nonExistentOrderId);
        });

        assertNotNull(exception);

        // Verify orderDetailMapper.getByOrderId was never called since orders is null
        verify(orderMapper).getById(nonExistentOrderId);
        verify(orderDetailMapper, never()).getByOrderId(any());
    }

    @Test
    @DisplayName("空值测试：当id为null时，details方法应抛出OrderBusinessException")
    void testDetails_NullId_ShouldHandleGracefully() {
        // Arrange
        Long nullId = null;
        when(orderMapper.getById(null)).thenReturn(null);

        // Act & Assert
        OrderBusinessException exception = assertThrows(OrderBusinessException.class, () -> {
            orderService.details(nullId);
        });

        assertNotNull(exception);

        // Verify
        verify(orderMapper).getById(nullId);
        verify(orderDetailMapper, never()).getByOrderId(any());
    }

    @Test
    @DisplayName("验证修复后空订单详情列表的处理")
    void testDetails_EmptyOrderDetailList_ShouldReturnEmptyList() {
        // Arrange
        Long orderId = 2L;
        Orders mockOrder = new Orders();
        mockOrder.setId(orderId);

        when(orderMapper.getById(orderId)).thenReturn(mockOrder);
        when(orderDetailMapper.getByOrderId(orderId)).thenReturn(Arrays.asList());

        // Act
        OrderVO result = orderService.details(orderId);

        // Assert
        assertNotNull(result);
        assertNotNull(result.getOrderDetailList());
        assertTrue(result.getOrderDetailList().isEmpty());

        // Verify
        verify(orderMapper).getById(orderId);
        verify(orderDetailMapper).getByOrderId(orderId);
    }
}
